<script setup lang="ts">
import { iconGroup } from './theme'
import { openCreate } from './create-document'
import { computed, onMounted, ref, watch } from 'vue'
import { reviewLabels, typeIcons, typeLabels, type QualityReport } from '../../schemas/src/index'
import { api, canEdit, canPublish, currentProject, dateLabel, projectDocuments, state } from './state'
defineEmits<{ search: [] }>()
const quality = ref<QualityReport | null>(null); const loading = ref(false); const error = ref('')
const recent = computed(() => [...projectDocuments.value].sort((a,b) => b.metadata.updated_at.localeCompare(a.metadata.updated_at)).slice(0,6))
const myDrafts = computed(() => (quality.value?.drafts ?? []).filter(d => d.editor === state.session?.user))
const awaitingMe = computed(() => canPublish.value ? (quality.value?.drafts ?? []).filter(d => d.review.status === 'in_review' && d.review.submitted_by !== state.session?.user) : [])
let sequence = 0
async function load() { const request = ++sequence; quality.value = null; if (!canEdit.value || !state.project) return; loading.value=true;error.value=''; try { const result = await api<QualityReport>(`/api/quality?project_id=${encodeURIComponent(state.project)}`); if(request===sequence) quality.value=result } catch(failure) {if(request===sequence)error.value=(failure as Error).message} finally {if(request===sequence)loading.value=false} }
onMounted(load); watch(() => state.project, load)
</script>
<template>
  <header class="workspace-heading"><div><span class="eyebrow">Không gian làm việc <span v-if="currentProject?.demo" class="demo-pill">Dữ liệu minh họa</span></span><h1>{{ currentProject?.name || 'Tri thức của đội ngũ' }}</h1><p>{{ currentProject?.description || 'Tìm thông tin nghiệp vụ, kiểm tra nguồn và cùng cập nhật kiến thức.' }}</p></div><v-btn v-if="canEdit && state.project" color="primary" prepend-icon="mdi-plus" @click="openCreate()">Tạo tài liệu</v-btn></header>
  <button class="dashboard-search" @click="$emit('search')"><v-icon icon="mdi-magnify" size="26" /><span><strong>Bạn đang cần hiểu điều gì?</strong><small>Tìm theo tên, ID hoặc nội dung · hỗ trợ tiếng Việt không dấu</small></span><kbd>Ctrl K</kbd></button>
  <div class="dashboard-columns"><section class="panel recent-panel"><div class="section-heading"><h2>Gần cập nhật</h2><a href="/library/" class="text-link">Xem thư viện <v-icon icon="mdi-arrow-right" size="18" /></a></div><a v-for="doc in recent" :key="doc.metadata.doc_id" :href="doc.url" class="recent-row document-row"><span class="document-icon"><v-icon :icon="typeIcons[doc.metadata.type]" :class="['semantic-icon',`semantic-${iconGroup(doc.metadata.type)}`]" size="22" /></span><div><strong>{{ doc.metadata.title }}</strong><small>{{ doc.metadata.doc_id }} · {{ typeLabels[doc.metadata.type] }}</small></div><time>{{ dateLabel(doc.metadata.updated_at) }}</time><v-icon icon="mdi-chevron-right" size="18" /></a><div v-if="!recent.length" class="empty-state"><v-icon icon="mdi-book-open-page-variant-outline" size="38" /><h2>Không gian đang chờ tri thức đầu tiên</h2><p>{{ canEdit ? 'Tạo hoặc import tài liệu, hoàn thiện nội dung rồi xuất bản cho đội ngũ.' : 'Tài liệu đã xuất bản của project sẽ xuất hiện tại đây.' }}</p><v-btn v-if="canEdit" href="/studio/" color="primary" variant="tonal">Bắt đầu biên tập</v-btn></div></section>
    <aside class="workspace-aside"><section v-if="canEdit" class="panel"><div class="section-heading"><h2>Việc của tôi</h2><v-icon icon="mdi-account-check-outline" color="primary" /></div><v-progress-linear v-if="loading" indeterminate color="primary" /><template v-if="awaitingMe.length"><span class="eyebrow">Chờ tôi duyệt</span><a v-for="doc in awaitingMe" :key="'review-'+doc.metadata.doc_id" href="/studio/reviews/" class="attention-row"><span>{{ doc.metadata.title }}<small class="d-block">{{ doc.metadata.doc_id }} · gửi bởi {{ doc.review.submitted_by }}</small></span><v-icon icon="mdi-chevron-right" size="18" /></a></template><template v-if="myDrafts.length"><span class="eyebrow">Bản nháp của tôi</span><a v-for="doc in myDrafts" :key="'mine-'+doc.metadata.doc_id" :href="`/studio/?doc=${doc.metadata.doc_id}`" class="attention-row"><span>{{ doc.metadata.title }}<small class="d-block">{{ doc.metadata.doc_id }} · {{ reviewLabels[doc.review.status] }}</small></span><v-icon icon="mdi-chevron-right" size="18" /></a></template><p v-if="!loading && !awaitingMe.length && !myDrafts.length" class="field-help">Bạn chưa có bản nháp nào. Chọn <strong>Tạo tài liệu</strong> hoặc mở một tài liệu rồi nhấn <strong>Chỉnh sửa</strong>.</p></section>
      <section v-if="canEdit" class="panel"><div class="section-heading"><h2>Cần chú ý</h2><v-icon icon="mdi-check-decagram-outline" color="primary" /></div><v-progress-linear v-if="loading" indeterminate color="primary" /><v-alert v-if="error" type="warning" variant="tonal">{{ error }}<v-btn variant="text" @click="load">Thử lại</v-btn></v-alert><a href="/studio/reviews/" class="attention-row"><span>Đang chờ duyệt</span><strong>{{ quality?.drafts.filter(d=>d.review.status==='in_review').length ?? '—' }}</strong></a><a href="/studio/" class="attention-row"><span>Cần chỉnh sửa</span><strong>{{ quality?.drafts.filter(d=>d.review.status==='changes_requested').length ?? '—' }}</strong></a><a href="/health/" class="attention-row"><span>Quá hạn rà soát</span><strong>{{ quality?.overdue.length ?? '—' }}</strong></a></section>
      <section class="panel"><div class="section-heading"><h2>Điểm bắt đầu</h2></div><a href="/screens/" class="quick-link"><span class="icon-tile semantic-screen"><v-icon icon="mdi-monitor" size="20" /></span><span><strong>Tra cứu màn hình</strong><small>Chức năng, thao tác và hành vi</small></span><v-icon icon="mdi-arrow-right" size="18" /></a><a href="/function-ids/" class="quick-link"><span class="icon-tile semantic-function"><v-icon icon="mdi-identifier" size="20" /></span><span><strong>Function ID &amp; Quy ước</strong><small>Tra mã và mở tài liệu nguồn</small></span><v-icon icon="mdi-arrow-right" size="18" /></a><a href="/help/" class="quick-link"><span class="icon-tile semantic-info"><v-icon icon="mdi-help-circle-outline" size="20" /></span><span><strong>Hướng dẫn sử dụng</strong><small>Đọc, biên tập, duyệt và xuất bản</small></span><v-icon icon="mdi-arrow-right" size="18" /></a></section>
    </aside></div>
</template>
